WITH remaining_keys AS (SELECT manager_id, id FROM employees EXCEPT DISTINCT SELECT manager_id, id FROM employees WHERE level = 'L4'), verified AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.manager_id = k.manager_id AND s.id = k.id) SELECT s.id, s.full_name, s.dept_id, s.job_title, s.is_remote, s.level, (SELECT SUM(e2.salary) FROM employees e2 WHERE e2.dept_id = s.dept_id) AS sum_employee_salary FROM verified s ORDER BY sum_employee_salary DESC NULLS FIRST, dept_id ASC;
